# ============================================================================
# CHIP-8 demo ROM assembler (two-pass, label resolution)
# ============================================================================
prog = []          # list of (kind, data) items
labels = {}        # name -> address (absolute)
fixups = []        # (index, label) where label is 12-bit immediate

def label(name):
    labels[name] = 0x200 + len(prog) * 2

def emit(*bytes_):
    prog.extend(bytes_)

def _fix(kind, args):
    if kind == 'label':
        label(args)
    else:
        prog.append((kind, args))
        fixups.append((len(prog) - 1, args))

# --- instruction emitters ---
def ld_vx_n(x, n):        emit(0x6000 + (x << 8) + n)
def ld_vx_vy(x, y):      emit(0x8000 + (x << 8) + y)
